-- Topic 3: GROUP BY + HAVING

-- 🟢 EASY — Q1–Q10
-- Q1 Find the total number of orders for each user_id.
SELECT user_id,COUNT(*)AS total_orders
FROM orders
GROUP BY user_id;
-- Q2 Find the total revenue generated by each user_id.
SELECT user_id,SUM(price_usd)AS total_revenue
FROM orders
GROUP BY user_id;
-- Q3 Find the average order price for each user_id.
SELECT user_id,AVG(price_usd)AS avg_order_price
FROM orders 
GROUP BY user_id;
-- Q4 Find the total COGS for each user_id.
SELECT user_id,SUM(cogs_usd)AS total_COGS
FROM orders
GROUP BY user_id;
-- Q5 Find the highest order price for each user_id.
SELECT user_id,MAX(price_usd) AS highest_order_price
FROM orders
GROUP BY user_id;
-- Q6 Find the lowest order price for each user_id.
SELECT user_id,MIN(price_usd)AS lowest_order_price
FROM orders
GROUP BY user_id;
-- Q7 Find the total number of orders for each primary_product_id.
SELECT primary_product_id,COUNT(*)AS total_orders
FROM orders
GROUP BY primary_product_id;
-- Q8 Find the total revenue associated with each primary_product_id.
SELECT
    primary_product_id,
    SUM(price_usd) AS total_revenue
FROM orders
GROUP BY primary_product_id;
-- Q9 Find the total number of orders for each items_purchased value.
SELECT items_purchased,COUNT(*)AS total_orders
FROM orders
GROUP BY items_purchased;
-- Q10 Find the average order price for each items_purchased value.
SELECT items_purchased,AVG(price_usd)AS avg_order_price
FROM orders
GROUP BY items_purchased;
-- 🟡 MEDIUM — Q11–Q20
-- Q11 Find the total revenue and total COGS for each primary_product_id.
SELECT primary_product_id,SUM(price_usd)AS total_revenue,SUM(cogs_usd)AS total_cogs
FROM orders
GROUP BY primary_product_id;
-- Q12 Find the total profit for each primary_product_id.(Profit = revenue − COGS)
SELECT primary_product_id,SUM(price_usd-cogs_usd)AS total_profit
FROM orders
GROUP BY primary_product_id;
-- Q13 Find the number of orders and average order price for each primary_product_id.
SELECT primary_product_id,COUNT(*)AS total_orders,AVG(price_usd)AS avg_price
FROM orders
GROUP BY primary_product_id;
-- Q14 Find the total revenue for each user_id, but show only customers whose total revenue is greater than $100.
SELECT user_id,SUM(price_usd)AS total_revenue
FROM orders
GROUP BY user_id
HAVING SUM(price_usd) > 100;
-- Q15 Find customers who have placed more than 1 order.
-- Display: user_id, number of orders
SELECT user_id,COUNT(*)AS total_orders
FROM orders
GROUP BY user_id
HAVING COUNT(*) > 1;
-- Q16 Find products that have generated more than $500 in total revenue.
SELECT product_id,SUM(price_usd) AS total_revenue
FROM order_items
GROUP BY product_id
HAVING SUM(price_usd)>500;
-- Q17 Find the average order price for each primary_product_id, but show only products whose average order price is greater than $50.
SELECT primary_product_id,AVG(price_usd)AS avg_price
FROM orders
GROUP BY primary_product_id
HAVING AVG(price_usd)>50;
-- Q18 For each items_purchased value, find:
-- - number of orders
-- - total revenue
-- - average order price
SELECT items_purchased,COUNT(*)AS total_orders,SUM(price_usd)AS total_revenue,AVG(price_usd)AS avg_price
FROM orders
GROUP BY items_purchased;
-- Q19 Find users whose total COGS is greater than $100.
SELECT user_id,SUM(cogs_usd)AS total_cogs
FROM orders
GROUP BY user_id
HAVING SUM(cogs_usd) > 100;
-- Q20 Find primary_product_id values where the total number of orders is greater than 1000.
SELECT primary_product_id,COUNT(*)AS total_orders
FROM orders
GROUP BY primary_product_id
HAVING COUNT(*)>1000;

-- 🔴 HARD — Q21–Q30
-- Q21 For each customer, calculate:
-- - number of orders
-- - total revenue
-- - total COGS
-- - total profit
-- Show only customers whose total profit is greater than $100.
SELECT 
    user_id,
    COUNT(*) AS total_orders,
    SUM(price_usd) AS total_revenue,
    SUM(cogs_usd) AS total_cogs,
    SUM(price_usd - cogs_usd) AS total_profit
FROM orders
GROUP BY user_id
HAVING SUM(price_usd - cogs_usd) > 100;
-- Q22 Find the customers who have placed at least 2 orders and whose average order price is greater than $50.
SELECT 
    user_id
FROM orders
GROUP BY user_id
HAVING COUNT(*) >= 2 
   AND AVG(price_usd) > 50;
-- Q23 For each primary_product_id, calculate total revenue and total profit. Show only products where total profit is greater than $1,000.
SELECT 
    primary_product_id,
    SUM(price_usd) AS total_revenue,
    SUM(price_usd - cogs_usd) AS total_profit
FROM orders
GROUP BY primary_product_id
HAVING SUM(price_usd - cogs_usd) > 1000;
-- Q24 Find the items_purchased category that has the highest total revenue.
SELECT 
    items_purchased,
    SUM(price_usd) AS total_revenue
FROM orders
GROUP BY items_purchased
ORDER BY total_revenue DESC
LIMIT 1;
-- Q25 For each user_id, calculate the difference between their highest and lowest order prices.
SELECT 
    user_id,
    (MAX(price_usd) - MIN(price_usd)) AS price_difference
FROM orders
GROUP BY user_id;

-- Q26 Find customers whose highest individual order is greater than $200, but whose average order price is below $100.
SELECT 
    user_id
FROM orders
GROUP BY user_id
HAVING MAX(price_usd) > 200 
   AND AVG(price_usd) < 100;

-- Q27 For each primary_product_id, calculate:
-- total revenue
-- total COGS
-- profit
-- Then show only products where profit margin is greater than 20%.
-- Profit margin = (profit / revenue) × 100
SELECT 
    primary_product_id,
    SUM(price_usd) AS total_revenue,
    SUM(cogs_usd) AS total_COGS,
    SUM(price_usd - cogs_usd) AS profit
FROM orders
GROUP BY primary_product_id
HAVING (SUM(price_usd - cogs_usd) / SUM(price_usd)) * 100 > 20;

-- Q28 Find customers who have placed more than 2 orders and whose total revenue is greater than $200.
SELECT 
    user_id
FROM orders
GROUP BY user_id
HAVING COUNT(*) > 2 
   AND SUM(price_usd) > 200;

-- Q29 For each primary_product_id, find:
-- - total orders
-- - total revenue
-- - average order price
-- - highest order price
-- - lowest order price
-- Show only products with at least 500 orders.
SELECT 
    primary_product_id,
    COUNT(*) AS total_orders,
    SUM(price_usd) AS total_revenue,
    AVG(price_usd) AS avg_order_price,
    MAX(price_usd) AS highest_order_price,
    MIN(price_usd) AS lowest_order_price
FROM orders
GROUP BY primary_product_id
HAVING COUNT(*) >= 500;

-- Q30 For each customer, calculate:
-- - number of orders
-- - total revenue
-- - average order price
-- - total COGS
-- - total profit
-- Then show only customers who:
-- - have at least 2 orders
-- - total revenue > $200
-- - total profit > $50
-- Sort the final result by total profit from highest to lowest.
SELECT 
    user_id,
    COUNT(*) AS total_orders,
    SUM(price_usd) AS total_revenue,
    AVG(price_usd) AS avg_order_price,
    SUM(cogs_usd) AS total_cogs,
    SUM(price_usd - cogs_usd) AS total_profit
FROM orders
GROUP BY user_id
HAVING COUNT(*) >= 2 
   AND SUM(price_usd) > 200 
   AND SUM(price_usd - cogs_usd) > 50
ORDER BY total_profit DESC;
